    if (!summary.isEmptyBuffer()) {
        summary.addSeparator();
        summary.addHeading('Organize photos', '1');
    }
    summary.addRaw(`Processed ${numFiles} file${numFiles !== 1 ? 's' : ''} with ${numErrors} error${numErrors !== 1 ? 's' : ''}`, true);
